function risingMarks(marks) {
    function longest(index, previous) {
        if (index === marks.length)
            return 0;
        let best = longest(index + 1, previous);
        if (marks[index] > previous)
            best = Math.max(best, 1 + longest(index + 1, marks[index]));
        return best;
    }
    return longest(0, -Infinity);
}

function risingMarks(marks) {
    const best = new Array(marks.length).fill(1);
    let longest = 0;
    for (let i = 0; i < marks.length; i++) {
        for (let j = 0; j < i; j++)
            if (marks[j] < marks[i])
                best[i] = Math.max(best[i], best[j] + 1);
        longest = Math.max(longest, best[i]);
    }
    return longest;
}

function risingMarks(marks) {
    const tails = [];
    for (const mark of marks) {
        let left = 0;
        let right = tails.length;
        while (left < right) {
            const middle = (left + right) >> 1;
            if (tails[middle] < mark)
                left = middle + 1;
            else
                right = middle;
        }
        tails[left] = mark;
    }
    return tails.length;
}
